    ISpecProvider specProvider = new OverridableSpecProvider(
        new TestSpecProvider(London.Instance),
        static r => new OverridableReleaseSpec(r) { IsEip7825Enabled = true });

    var config = new TxPoolConfig { GasLimit = long.MaxValue };
